            } else {
                *c -= 1;
                Some(Permit { sem: self })
            }
        }

        pub fn release(&self) {
            let mut c = self.count.lock().unwrap();
            *c += 1;
            self.cv.notify_one();
        }
    }

    pub struct Permit<'a> {
        sem: &'a Semaphore,
    }

    impl<'a> Drop for Permit<'a> {
        fn drop(&mut self) {
            self.sem.release();
        }
    }
