        outer(a_outer, b_outer);
    });

    h_outer.join().unwrap();

    println!("DONE done=1");
}

fn outer(a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) {
    let a1 = Arc::clone(&a);
    let b1 = Arc::clone(&b);
    let a2 = Arc::clone(&a);
    let b2 = Arc::clone(&b);

    let h_x1 = thread::spawn(move || {
        x1(a1, b1);
    });
    let h_x2 = thread::spawn(move || {
        x2(a2, b2);
    });

    h_x1.join().unwrap();
    h_x2.join().unwrap();
}

