    {
        let mut guard = m.lock().unwrap();
        compute();
        let mut tmp = guard.acc;
        tmp = tmp + 1;
        guard.acc = tmp;
    }
}

fn w2(m: Arc<Mutex<Shared>>) {
    {
        let mut guard = m.lock().unwrap();
        compute();
        let mut tmp = guard.acc;
        tmp = tmp + 1;
        guard.acc = tmp;
    }
}

